package io.github.diodeme.ji.agent.core;

import io.github.diodeme.ji.ai.CancellationToken;
import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import io.github.diodeme.ji.extension.PermissionDecider;
import io.github.diodeme.ji.extension.ToolExecutionPolicy;
import io.github.diodeme.ji.extension.ToolInterceptor;
import io.github.diodeme.ji.extension.ToolRetryContract;
import java.time.Clock;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.OptionalLong;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CompletionException;
import java.util.concurrent.CompletionStage;
import java.util.concurrent.Executor;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Supplier;
import java.util.function.LongPredicate;

/** Ordered-preflight, bounded Tool effect scheduler shared by all inbound transports. */
public final class ToolBatchScheduler implements AutoCloseable {
    public static final int DEFAULT_SESSION_LIMIT = 8;
    public static final int DEFAULT_HOST_LIMIT = 32;
    public static final int DEFAULT_QUEUE_LIMIT = 1_024;
    private final ToolExecutionPolicy policy;
    private final PermissionCoordinator permissions;
    private final List<ToolInterceptor> interceptors;
    private final Executor effectExecutor;
    private final Clock clock;
    private final int sessionLimit;
    private final int hostLimit;
    private final int queueLimit;
    private final Object lock = new Object();
    private final ArrayDeque<QueuedEffect<?>> queued = new ArrayDeque<>();
    private final Map<String, Integer> sessionActive = new java.util.HashMap<>();
    private final AtomicBoolean closed = new AtomicBoolean();
    private int hostActive;

    public ToolBatchScheduler(ToolExecutionPolicy policy, PermissionDecider decider,
                              List<ToolInterceptor> interceptors, Executor effectExecutor, Clock clock) {
        this(policy, decider, interceptors, effectExecutor, clock,
                DEFAULT_SESSION_LIMIT, DEFAULT_HOST_LIMIT, DEFAULT_QUEUE_LIMIT);
    }

    public ToolBatchScheduler(ToolExecutionPolicy policy, PermissionDecider decider,
                              List<ToolInterceptor> interceptors, Executor effectExecutor, Clock clock,
                              int sessionLimit, int hostLimit, int queueLimit) {
        if (policy == null || decider == null || interceptors == null || effectExecutor == null || clock == null) {
            throw new IllegalArgumentException("scheduler dependencies must not be null");
        }
        if (sessionLimit < 1 || hostLimit < sessionLimit || queueLimit < 1) {
            throw new IllegalArgumentException("invalid scheduler limits");
        }
        this.policy = policy;
        permissions = new PermissionCoordinator(decider, clock);
        this.interceptors = List.copyOf(interceptors);
        this.effectExecutor = effectExecutor;
        this.clock = clock;
        this.sessionLimit = sessionLimit;
        this.hostLimit = hostLimit;
        this.queueLimit = queueLimit;
    }

    public <T> CompletionStage<BatchResult<T>> execute(List<ToolRequest<T>> requests,
                                                        CancellationToken cancellation) {
        if (requests == null || requests.isEmpty()) throw new IllegalArgumentException("requests must not be empty");
        if (cancellation == null) throw new IllegalArgumentException("cancellation must not be null");
        if (closed.get()) return CompletableFuture.failedFuture(error(ErrorCode.RUNTIME_CLOSED,
                Map.of("resource", "tool-batch-scheduler")));
        var prepared = new ArrayList<Prepared<T>>();
        CompletableFuture<Void> preflight = CompletableFuture.completedFuture(null);
        for (ToolRequest<T> request : List.copyOf(requests)) {
            preflight = preflight.thenCompose(ignored -> preflight(request, cancellation)
                    .thenAccept(prepared::add));
        }
        return preflight.thenCompose(ignored -> executePrepared(prepared, cancellation));
    }

    private <T> CompletableFuture<Prepared<T>> preflight(ToolRequest<T> request,
                                                          CancellationToken cancellation) {
        cancellation.throwIfCancellationRequested();
        ToolExecutionPolicy.Evaluation evaluation = policy.evaluate(request.context());
        if (evaluation.action() == ToolExecutionPolicy.Action.DENY) {
            return CompletableFuture.failedFuture(error(ErrorCode.TOOL_POLICY_DENIED,
                    Map.of("tool", request.context().toolName(), "ruleId", evaluation.ruleId())));
        }
        ToolInterceptor.ToolInvocation invocation = new ToolInterceptor.ToolInvocation(
                request.context(), request.operationId(), request.operationRevision());
        CompletableFuture<Void> chain = CompletableFuture.completedFuture(null);
        for (ToolInterceptor interceptor : interceptors) {
            chain = chain.thenCompose(ignored -> interceptor.before(invocation).toCompletableFuture());
        }
        if (evaluation.action() != ToolExecutionPolicy.Action.ASK) {
            return chain.thenApply(ignored -> new Prepared<>(request, evaluation, invocation, null));
        }
        PermissionDecider.Request permission = request.permission();
        if (permission == null) throw new IllegalArgumentException("ASK policy requires permission request");
        return chain.thenCompose(ignored -> permissions.decide(permission, cancellation))
                .thenCompose(decision -> {
                    request.lifecycle().permissionResolved(decision);
                    return decision.outcome() == PermissionDecider.Outcome.ALLOW
                            ? CompletableFuture.completedFuture(new Prepared<>(request, evaluation, invocation, decision))
                            : CompletableFuture.failedFuture(error(ErrorCode.PERMISSION_DENIED,
                                    Map.of("permissionId", permission.permissionId(),
                                            "tool", request.context().toolName())));
                });
    }

    private <T> CompletableFuture<BatchResult<T>> executePrepared(List<Prepared<T>> prepared,
                                                                   CancellationToken cancellation) {
        boolean sequential = prepared.stream().anyMatch(value -> value.evaluation().sequential());
        List<CompletableFuture<ItemResult<T>>> effects = new ArrayList<>();
        if (sequential) {
            CompletableFuture<Void> prior = CompletableFuture.completedFuture(null);
            for (Prepared<T> value : prepared) {
                CompletableFuture<ItemResult<T>> current = prior.thenCompose(ignored -> schedule(value, cancellation));
                effects.add(current);
                prior = current.thenApply(ignored -> null);
            }
        } else {
            for (Prepared<T> value : prepared) effects.add(schedule(value, cancellation));
        }
        return CompletableFuture.allOf(effects.toArray(CompletableFuture[]::new))
                .thenApply(ignored -> new BatchResult<>(effects.stream().map(CompletableFuture::join).toList(), sequential));
    }

    private <T> CompletableFuture<ItemResult<T>> schedule(Prepared<T> prepared,
                                                           CancellationToken cancellation) {
        CompletableFuture<ItemResult<T>> result = new CompletableFuture<>();
        QueuedEffect<T> queuedEffect = new QueuedEffect<>(prepared, cancellation, result);
        synchronized (lock) {
            if (closed.get()) return CompletableFuture.failedFuture(error(ErrorCode.RUNTIME_CLOSED,
                    Map.of("resource", "tool-batch-scheduler")));
            if (queued.size() >= queueLimit) return CompletableFuture.failedFuture(error(ErrorCode.TOOL_BATCH_QUEUE_FULL,
                    Map.of("scope", "host", "limit", Integer.toString(queueLimit))));
            queued.addLast(queuedEffect);
            drainLocked();
        }
        cancellation.cancellation().thenRun(() -> {
            synchronized (lock) {
                if (queued.remove(queuedEffect)) result.completeExceptionally(error(ErrorCode.OPERATION_CANCELLED,
                        Map.of("operationId", prepared.request().operationId())));
            }
        });
        return result;
    }

    private void drainLocked() {
        boolean progressed;
        do {
            progressed = false;
            var iterator = queued.iterator();
            while (iterator.hasNext() && hostActive < hostLimit) {
                QueuedEffect<?> effect = iterator.next();
                String sessionId = effect.prepared().request().context().sessionId();
                int active = sessionActive.getOrDefault(sessionId, 0);
                if (active >= sessionLimit) continue;
                iterator.remove();
                hostActive++;
                sessionActive.put(sessionId, active + 1);
                dispatch(effect);
                progressed = true;
            }
        } while (progressed && hostActive < hostLimit && !queued.isEmpty());
    }

    private <T> void dispatch(QueuedEffect<T> effect) {
        effectExecutor.execute(() -> {
            ItemResult<T> item = null;
            Throwable failure = null;
            ToolInterceptor.Status status = ToolInterceptor.Status.FAILED;
            try {
                effect.cancellation().throwIfCancellationRequested();
                ToolRequest<T> request = effect.prepared().request();
                ToolExecutionPolicy.Evaluation current = policy.evaluate(request.context());
                if (current.action() == ToolExecutionPolicy.Action.DENY) {
                    throw error(ErrorCode.TOOL_POLICY_DENIED,
                            Map.of("tool", request.context().toolName(), "ruleId", current.ruleId()));
                }
                if (current.action() == ToolExecutionPolicy.Action.ASK) {
                    PermissionDecider.Decision decision = effect.prepared().permissionDecision();
                    PermissionDecider.Request permission = request.permission();
                    if (decision == null || permission == null || decision.outcome() != PermissionDecider.Outcome.ALLOW
                            || !permission.permissionId().equals(decision.permissionId())
                            || permission.revision() != decision.requestRevision()
                            || !clock.instant().isBefore(permission.expiresAt())) {
                        throw error(ErrorCode.PERMISSION_EXPIRED,
                                Map.of("permissionId", permission == null ? "missing" : permission.permissionId()));
                    }
                }
                if (!request.validity().test(request.operationRevision())) {
                    throw stale(request, request.operationRevision());
                }
                long runningRevision = request.lifecycle().started(
                        request.operationId(), request.operationRevision());
                if (!request.validity().test(runningRevision)) throw stale(request, runningRevision);
                T value = request.effect().get();
                effect.cancellation().throwIfCancellationRequested();
                if (!request.validity().test(runningRevision)) throw stale(request, runningRevision);
                item = new ItemResult<>(request.operationId(), runningRevision, value);
                status = ToolInterceptor.Status.SUCCEEDED;
            } catch (Throwable thrown) {
                failure = unwrap(thrown);
                status = failure instanceof JiException ji
                        && ji.error().code() == ErrorCode.OPERATION_STALE_COMPLETION
                        ? ToolInterceptor.Status.STALE
                        : failure instanceof java.util.concurrent.CancellationException
                        ? ToolInterceptor.Status.CANCELLED : ToolInterceptor.Status.FAILED;
            }
            Throwable completionFailure = notifyAfter(effect.prepared().invocation(), status);
            if (failure == null && completionFailure != null) failure = completionFailure;
            if (failure == null) effect.result().complete(item);
            else effect.result().completeExceptionally(failure);
            release(effect.prepared().request().context().sessionId());
        });
    }

    private Throwable notifyAfter(ToolInterceptor.ToolInvocation invocation, ToolInterceptor.Status status) {
        try {
            ToolInterceptor.ToolCompletion completion = new ToolInterceptor.ToolCompletion(
                    invocation.operationId(), invocation.operationRevision(), status);
            CompletableFuture<Void> chain = CompletableFuture.completedFuture(null);
            for (ToolInterceptor interceptor : interceptors) {
                chain = chain.thenCompose(ignored -> interceptor.after(invocation, completion).toCompletableFuture());
            }
            chain.join();
            return null;
        } catch (CompletionException exception) {
            return unwrap(exception);
        }
    }

    private void release(String sessionId) {
        synchronized (lock) {
            hostActive--;
            int remaining = sessionActive.getOrDefault(sessionId, 1) - 1;
            if (remaining == 0) sessionActive.remove(sessionId);
            else sessionActive.put(sessionId, remaining);
            drainLocked();
        }
    }

    public SchedulerSnapshot snapshot() {
        synchronized (lock) {
            return new SchedulerSnapshot(hostActive, Map.copyOf(sessionActive), queued.size());
        }
    }

    @Override
    public void close() {
        if (!closed.compareAndSet(false, true)) return;
        synchronized (lock) {
            while (!queued.isEmpty()) {
                QueuedEffect<?> effect = queued.removeFirst();
                effect.result().completeExceptionally(error(ErrorCode.OPERATION_CANCELLED,
                        Map.of("operationId", effect.prepared().request().operationId())));
            }
        }
    }

    public record ToolRequest<T>(ToolExecutionPolicy.Context context, String operationId,
                                 long operationRevision, PermissionDecider.Request permission,
                                 ToolRetryContract retryContract, String durableResumeToken,
                                 Lifecycle lifecycle, LongPredicate validity, Supplier<T> effect) {
        public ToolRequest {
            if (context == null || operationId == null || operationId.isBlank() || operationRevision < 0
                    || lifecycle == null || validity == null || effect == null) {
                throw new IllegalArgumentException("invalid Tool request");
            }
            retryContract = ToolRetryContract.failClosed(retryContract);
        }

        public boolean mayResume() {
            return retryContract.mayResume(durableResumeToken);
        }
    }

    public record ItemResult<T>(String operationId, long operationRevision, T value) {}
    public record BatchResult<T>(List<ItemResult<T>> items, boolean sequential) {
        public BatchResult { items = List.copyOf(items); }
    }
    public record SchedulerSnapshot(int hostActive, Map<String, Integer> sessionActive, int queued) {}
    public interface Lifecycle {
        void permissionResolved(PermissionDecider.Decision decision);
        long started(String operationId, long preparedRevision);

        static Lifecycle unmanaged() {
            return new Lifecycle() {
                @Override public void permissionResolved(PermissionDecider.Decision decision) {}
                @Override public long started(String operationId, long preparedRevision) {
                    return preparedRevision;
                }
            };
        }
    }
    private record Prepared<T>(ToolRequest<T> request, ToolExecutionPolicy.Evaluation evaluation,
                               ToolInterceptor.ToolInvocation invocation,
                               PermissionDecider.Decision permissionDecision) {}
    private record QueuedEffect<T>(Prepared<T> prepared, CancellationToken cancellation,
                                   CompletableFuture<ItemResult<T>> result) {}

    private static JiException stale(ToolRequest<?> request, long completionRevision) {
        return error(ErrorCode.OPERATION_STALE_COMPLETION,
                Map.of("operationId", request.operationId(),
                        "expectedRevision", Long.toString(request.operationRevision()),
                        "completionRevision", Long.toString(completionRevision)));
    }

    private static Throwable unwrap(Throwable failure) {
        return failure instanceof CompletionException && failure.getCause() != null ? failure.getCause() : failure;
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters) {
        return new JiException(new JiError(code, parameters, java.util.Optional.empty(),
                java.util.Optional.empty(), OptionalLong.empty()));
    }
}

